Array.isArray().description:
ES5
Array.isArray(value);
return 'true' if the value is an Array; otherwise, 'false'.

Array.fromAsync().description:
ES2026
Array.fromAsync(asyncIterableOrLike[, mapFn[, thisArg]]);
return a Promise for a new Array instance, awaiting each value from an async iterable, an iterable of promises, or an array-like of promises.

Array.of(elementN).description:
ES2015
Array.of(elementN);
return a new Array instance.

Array.prototype.copyWithin().description:
ES2015
array.copyWithin(target[, start[, end]]);
return the modified array

Array.prototype.fill().description:
ES2015
array.fill(value[, start[, end]]);
return the modified array

Array.prototype.filter().description:
ES5
let newArray = array.filter(callbackFn(element[, index[, array]])[, thisArg]);
return a new array

Array.prototype.find().description:
ES2015
array.find(callbackFn[, thisArg]);
return the value of the first element in the array that satisfies the provided testing function. Otherwise 'undefined' is returned.

Array.prototype.findLast().description:
ES2023
array.findLast(callbackFn[, thisArg]);
return the value of the last element in the array that satisfies the provided testing function, iterating from the end. Otherwise 'undefined' is returned.

Array.prototype.findLastIndex().description:
ES2023
array.findLastIndex(callbackFn(element[, index[, array]])[, thisArg]);
return the index of the last element in the array that satisfies the provided testing function, iterating from the end. Otherwise, it returns '-1'.

Array.prototype.flat().description:
ES2019
let newArray = array.flat([depth]);
return a new array

Array.prototype.flatMap().description:
ES2019
let newArray = array.flatMap(function callbackFn(currentValue[, index[, array]]) { }[, thisArg]);
return a new array with each element being the result of the callback function and flattened to a depth of '1'.

Array.prototype.includes().description:
ES2016
array.includes(valueToFind[, fromIndex]);
return a Boolean value

Array.prototype.indexOf().description:
ES5
array.indexOf(searchElement[, fromIndex]);
return the first index of the element in the array; '-1' if not found.

Array.prototype.lastIndexOf().description:
ES5
array.lastIndexOf(searchElement[, fromIndex]);
return the last index of the element in the array; '-1' if not found.

Array.prototype.map().description:
ES5
let newArray = array.map(function callbackFn(currentValue[, index[, array]]) { }[, thisArg]);
return a new array with each element being the result of the callback function.

Array.prototype.reduce().description:
ES5
array.reduce(callbackFn(previousValue, currentValue[, index[, array]]), [, initialValue]);
return The single value that results from the reduction.

Array.prototype.reduceRight().description:
ES5
array.reduceRight(callbackFn(accumulator, currentValue[, index[, array]])[, initialValue]);
return the value that results from the reduction.

Array.prototype.toReversed().description:
ES2023
array.toReversed();
the copying counterpart of `reverse()` — return a new reversed array, leaving the original array unchanged.

Array.prototype.with().description:
ES2023
array.with(index, value);
the copying counterpart of index assignment (`arr[index] = value`) — return a new array with the element at `index` replaced by `value`, leaving the original array unchanged.

Array.prototype.toSorted().description:
ES2023
array.toSorted([compareFunction(firstEl, secondEl)]);
the copying counterpart of `sort()` — return a new sorted array, leaving the original array unchanged.

Array.prototype.splice().description:
let arrDeletedItems = array.splice(start[, deleteCount[, item1[, item2[, ...]]]]);
changes the contents of an array by removing or replacing existing elements and/or adding new elements in-place.
return an array containing the deleted elements,
If no elements are removed, an empty array is returned.

Array.prototype.toSpliced().description:
ES2023
let newArray = array.toSpliced(start[, deleteCount[, item1[, item2[, ...]]]]);
the copying counterpart of `splice()` — return a new array with the changes applied, leaving the original array unchanged.

Array.prototype.entries().description:
